import{_ as a}from"./chunks/购买中心vps.DK2X6Ykd.js";import{_ as r,o as p,c as o,a2 as n}from"./chunks/framework.BXzK3EA4.js";const i="/assets/%E5%AE%A2%E6%88%B7%E4%B8%AD%E5%BF%8311.B8l6XSXX.png",l="/assets/%E6%96%B0%E8%B4%AD%E4%B9%B0%E7%8B%AC%E7%AB%8B%E4%BA%91%E7%9B%98.CG1KLOWg.png",e="/assets/%E9%80%89%E6%8B%A9%E4%BA%91%E7%9B%98%E9%85%8D%E7%BD%AE.Y76l3LNg.png",g="/assets/%E4%BA%91%E7%A1%AC%E7%9B%98%E7%BB%93%E7%AE%97%E5%B8%90%E5%8D%9511.DWmUslF0.png",t="/assets/%E6%9F%A5%E7%9C%8B%E7%8B%AC%E7%AB%8B%E4%BA%91%E7%9B%981.BErIozRm.png",E="/assets/%E7%8B%AC%E7%AB%8B%E4%BA%91%E7%9B%981.BXRqfRI_.png",c="/assets/%E7%A1%AE%E8%AE%A4%E6%8F%90%E4%BA%A4%E6%8C%82%E8%BD%BD.BHqoj5CA.png",B="/assets/%E6%8C%82%E8%BD%BD%E6%88%90%E5%8A%9F11.CvbllcV8.png",m="/assets/%E5%8D%B8%E8%BD%BD%E4%BA%91%E7%9B%9811.BSkkIwJ-.png",h="/assets/%E7%A1%AE%E8%AE%A4%E5%8D%B8%E8%BD%BD.CL8jmrHP.png",_="/assets/%E5%8D%B8%E8%BD%BD%E4%BA%91%E7%9B%98%E6%88%90%E5%8A%9F11.abRvLEXy.png",S=JSON.parse('{"title":"独立云盘","description":"","frontmatter":{"title":"独立云盘"},"headers":[],"relativePath":"vps/manage-vps/cloud-disk.md","filePath":"vps/manage-vps/cloud-disk.md","lastUpdated":1788185904000}'),d={name:"vps/manage-vps/cloud-disk.md"};function A(u,s,P,D,f,b){return p(),o("div",null,[...s[0]||(s[0]=[n('<h3 id="购买独立云盘" tabindex="-1">购买独立云盘 <a class="header-anchor" href="#购买独立云盘" aria-label="Permalink to &quot;购买独立云盘&quot;">​</a></h3><p>独立云盘可用作 VPS 的数据盘，当 VPS 的存储容量不够时，可以将已购买的独立云盘挂载到 VPS，或升级独立云盘来扩充存储容量。本文主要介绍通过 Raksmart 控制台购买全新的独立云盘。</p><h4 id="使用限制" tabindex="-1">使用限制 <a class="header-anchor" href="#使用限制" aria-label="Permalink to &quot;使用限制&quot;">​</a></h4><p>独立云盘只能挂载到同一区域、同一可用区内的 VPS 实例，无法跨区域或跨可用区挂载。</p><h4 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h4><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">Raksmart 控制台</a>。</p></li><li><p>在官网顶部导航右侧，单击<strong>控制台</strong>，进入控制台客户中心页面。</p><p><img src="'+i+'" alt="客户中心11.png"></p></li><li><p>单击<strong>购买中心</strong>，进入<strong>购物车</strong>页面。</p><p><img src="'+a+'" alt="购买中心vps.png"></p></li><li><p>单击 <strong>VPS</strong> -&gt; <strong>独立云盘</strong>，进入<strong>配置</strong> - <strong>购物车</strong>页面。</p><p><img src="'+l+'" alt="新购买独立云盘.png"></p></li><li><p>根据业务需求完成配置选择，单击<strong>继续</strong>。</p><p><img src="'+e+'" alt="选择云盘配置.png"></p></li><li><p>完成费用结算。</p><p><img src="'+g+'" alt="云硬盘结算帐单11.png"></p></li></ol><hr><h3 id="挂载独立云盘" tabindex="-1">挂载独立云盘 <a class="header-anchor" href="#挂载独立云盘" aria-label="Permalink to &quot;挂载独立云盘&quot;">​</a></h3><p>购买并开通独立云盘后，可挂载到指定 VPS。</p><h4 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h4><p>已经购买独立云盘。详细内容介绍可参考<a href="#购买独立云盘">购买独立云盘</a>。</p><h4 id="使用限制-1" tabindex="-1">使用限制 <a class="header-anchor" href="#使用限制-1" aria-label="Permalink to &quot;使用限制&quot;">​</a></h4><p>独立云盘只能挂载到同一区域、同一可用区内的 VPS 实例，无法跨区域或跨可用区绑定。</p><h4 id="操作步骤-1" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤-1" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h4><ol><li><p>在 VPS <strong>管理产品</strong>页面，单击<strong>独立云盘</strong>面板。</p><p><img src="'+t+'" alt="查看独立云盘1.png"></p></li><li><p>选择一个独立云盘单击<strong>挂载</strong>。</p><p><img src="'+E+'" alt="独立云盘1.png"></p></li><li><p>在确认提示页面，单击<strong>提交</strong>。</p><p><img src="'+c+'" alt="确认提交挂载.png"></p></li><li><p>成功挂载独立云盘后，系统提示如下状态。</p><p><img src="'+B+'" alt="挂载成功11.png"></p></li></ol><hr><h3 id="卸载独立云盘" tabindex="-1">卸载独立云盘 <a class="header-anchor" href="#卸载独立云盘" aria-label="Permalink to &quot;卸载独立云盘&quot;">​</a></h3><p>卸载独立云盘是指在控制台将独立云盘与 VPS 解除挂载关系，卸载只是断开连接，不会删除云盘里的数据。</p><ol><li><p>在 VPS <strong>管理产品</strong>页面，单击<strong>独立云盘</strong>面板。</p><p><img src="'+t+'" alt="查看独立云盘1.png"></p></li><li><p>如果此面板下有多个独立云盘，选择一个单击<strong>卸载</strong>。</p><p><img src="'+m+'" alt="卸载云盘11.png"></p></li><li><p>在确认提示页面，单击<strong>提交</strong>。</p><p><img src="'+h+'" alt="确认卸载.png"></p></li><li><p>成功卸载独立云盘后，系统提示如下状态。云盘会进入 “挂载” 状态，之后可以重新挂载到同地域的其他VPS上。</p><p><img src="'+_+'" alt="卸载云盘成功11.png"></p></li></ol>',19)])])}const V=r(d,[["render",A]]);export{S as __pageData,V as default};
